def search_pubmed(title_abstract_keywords=None, authors=None, num_results=None, **_extra):
    import json, os, datetime, hashlib, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0330000" if __import__("os").path.isdir("./environment_mix/0330000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Defaults per tool schema
    if title_abstract_keywords is None:
        title_abstract_keywords = []
    if authors is None:
        authors = []
    if num_results is None:
        num_results = 10

    # Load DB
    clients = _load("api_clients.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    articles = _load("articles.json")
    article_fetches = _load("article_fetches.json")

    # Resolve ambient auth: pick any active client that can still make calls (quota check)
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _count_calls_last_24h(client_id):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(hours=24)
        cnt = 0
        for r in search_requests:
            if r.get("client_id") == client_id:
                dt = _parse_dt(r.get("created_at"))
                if dt and dt >= cutoff:
                    cnt += 1
        for f in article_fetches:
            if f.get("client_id") == client_id:
                dt = _parse_dt(f.get("created_at"))
                if dt and dt >= cutoff:
                    cnt += 1
        return cnt

    chosen_client = None
    auth_error = None
    for c in clients:
        if c.get("status") != "active":
            continue
        dq = c.get("daily_request_quota")
        if not isinstance(dq, int) or dq < 0:
            continue
        used = _count_calls_last_24h(c.get("id"))
        if used <= dq:
            chosen_client = c
            break
    if not chosen_client:
        # Determine whether it's quota vs status
        any_active = any(c.get("status") == "active" for c in clients)
        if not any_active:
            auth_error = _err("UNAUTHORIZED", "No active client available to serve request.")
        else:
            auth_error = _err("QUOTA_EXCEEDED", "Daily request quota exceeded for all active clients.")
        # Even though this tool has no credential param, enforce ambient auth+quota.
        return auth_error

    # Validate inputs
    if not isinstance(title_abstract_keywords, list) or any(not isinstance(x, str) for x in title_abstract_keywords):
        return _err("VALIDATION_ERROR", "title_abstract_keywords must be an array of strings.")
    if not isinstance(authors, list) or any(not isinstance(x, str) for x in authors):
        return _err("VALIDATION_ERROR", "authors must be an array of strings.")
    if not isinstance(num_results, int) or num_results <= 0:
        return _err("VALIDATION_ERROR", "num_results must be a positive integer.")
    if num_results < 1 or num_results > 200:
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 200.")

    # Normalize + query_hash (deterministic)
    def _norm_arr(a):
        return [(" ".join(s.split())).strip().lower() for s in a if isinstance(s, str)]

    norm = {
        "title_abstract_keywords": _norm_arr(title_abstract_keywords),
        "authors": _norm_arr(authors),
        "num_results": num_results,
    }
    qh = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    # Find or create search_request (unique(query_hash))
    sr = None
    for r in search_requests:
        if r.get("query_hash") == qh:
            sr = r
            break

    created_new = False
    if sr is None:
        sr_id = "sr_" + uuid.uuid4().hex
        sr = {
            "id": sr_id,
            "client_id": chosen_client.get("id"),
            "title_abstract_keywords": list(title_abstract_keywords),
            "authors": list(authors),
            "num_results": num_results,
            "query_hash": qh,
            "status": "queued",
            "error_message": None,
            "remote_provider": "pubmed_eutils",
            "remote_request_id": None,
            "completed_at": None,
            "created_at": now,
            "updated_at": now,
        }
        # FK: client exists (chosen_client)
        search_requests.append(sr)
        created_new = True

    # If cached succeeded exists, return its results (up to num_results)
    def _sr_results(sr_id):
        rows = [x for x in search_results if x.get("search_request_id") == sr_id]
        rows.sort(key=lambda x: x.get("rank", 10**9))
        return rows

    # Helper to fabricate deterministic PMID list from query_hash (offline stand-in)
    def _gen_pmids(qhash, n):
        pmids = []
        seed = bytes.fromhex(qhash)
        for i in range(n):
            h = hashlib.sha256(seed + str(i).encode("utf-8")).hexdigest()
            # numeric-looking PMID between 1 and 99999999
            pmid_num = int(h[:8], 16) % 99999999 + 1
            pmids.append(str(pmid_num))
        # Ensure uniqueness while preserving order
        seen = set()
        out = []
        for p in pmids:
            if p not in seen:
                seen.add(p)
                out.append(p)
        return out

    # Process lifecycle transitions: queued -> running -> succeeded with results insertion
    def _can_transition(cur, nxt):
        trans = {
            "queued": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        return nxt in trans.get(cur, [])

    # If newly created or not succeeded yet, (re)run to succeeded (idempotent: if already succeeded, don't reinsert)
    if sr.get("status") != "succeeded":
        # queued -> running
        cur = sr.get("status")
        if cur != "running":
            if not _can_transition(cur, "running"):
                sr["status"] = "failed"
                sr["error_message"] = "Invalid state; cannot transition to running."
                sr["updated_at"] = now
            else:
                sr["status"] = "running"
                sr["updated_at"] = now

        # running -> succeeded
        if sr.get("status") == "running":
            pmids = _gen_pmids(qh, sr.get("num_results") or num_results)
            existing = _sr_results(sr["id"])
            if not existing:
                # Insert contiguous ranks starting at 1, N <= num_results
                n = min(len(pmids), int(sr.get("num_results")))
                used_pubmed = set()
                # enforce uniqueness (search_request_id, pubmed_id) and (search_request_id, rank)
                for i in range(n):
                    pmid = pmids[i]
                    if pmid in used_pubmed:
                        continue
                    used_pubmed.add(pmid)
                    rank = i + 1
                    # unique constraints check against store
                    if any((x.get("search_request_id") == sr["id"] and x.get("rank") == rank) for x in search_results):
                        continue
                    if any((x.get("search_request_id") == sr["id"] and x.get("pubmed_id") == pmid) for x in search_results):
                        continue
                    if not (1 <= len(pmid) <= 32):
                        continue
                    rid = "sres_" + uuid.uuid4().hex
                    search_results.append({
                        "id": rid,
                        "search_request_id": sr["id"],
                        "pubmed_id": pmid,
                        "rank": rank,
                        "created_at": now,
                        "updated_at": now,
                    })
            # mark succeeded
            if not _can_transition(sr.get("status"), "succeeded"):
                sr["status"] = "failed"
                sr["error_message"] = "Invalid state; cannot transition to succeeded."
                sr["updated_at"] = now
            else:
                sr["status"] = "succeeded"
                sr["error_message"] = None
                sr["completed_at"] = now
                sr["updated_at"] = now

    # Persist changes (including reusing existing row with no mutation should still persist if we mutated status/results)
    if created_new or sr.get("updated_at") == now:
        _save("search_requests.json", search_requests)
        _save("search_results.json", search_results)

    # Build response
    if sr.get("status") == "failed":
        # Record already in search_requests as an audit row; return failure
        return _err("NOT_FOUND", "Query could not be fulfilled.", query_hash=qh, request_id=sr.get("id"), details=sr.get("error_message"))

    rows = _sr_results(sr["id"])
    rows = [r for r in rows if isinstance(r.get("rank"), int)]
    rows.sort(key=lambda x: x["rank"])
    # Trim to requested num_results of this call (tool says single page limited by num_results)
    rows = rows[:num_results]
    results_payload = []
    for r in rows:
        pmid = r.get("pubmed_id")
        results_payload.append({
            "pubmed_id": pmid,
            "rank": r.get("rank"),
            "source_url": f"https://pubmed.ncbi.nlm.nih.gov/{pmid}/" if pmid else None,
        })

    latency_ms = int((time.time() - t0) * 1000)
    # No dedicated request-log collection in schema; dynamics are recorded via search_requests/article_fetches creation only.
    return {
        "search_request": {
            "id": sr.get("id"),
            "client_id": sr.get("client_id"),
            "query_hash": sr.get("query_hash"),
            "status": sr.get("status"),
            "remote_provider": sr.get("remote_provider"),
            "created_at": sr.get("created_at"),
            "completed_at": sr.get("completed_at"),
        },
        "results": results_payload,
        "meta": {
            "requested_num_results": num_results,
            "returned": len(results_payload),
            "latency_ms": latency_ms,
        }
    }

def format_paper_details(pubmed_ids, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0330000" if __import__("os").path.isdir("./environment_mix/0330000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "format_paper_details"

    def _now_utc():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso_z():
        return _now_utc().isoformat() + "Z"

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo is None else s.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1])
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                return dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _count_calls_last_24h(client_id, search_requests_rows, article_fetch_rows):
        cutoff = _now_utc() - datetime.timedelta(hours=24)
        cnt = 0
        for r in search_requests_rows:
            if r.get("client_id") != client_id:
                continue
            dt = _parse_dt_any(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        for f in article_fetch_rows:
            if f.get("client_id") != client_id:
                continue
            dt = _parse_dt_any(f.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt

    def _gen_id(prefix):
        # timestamp ms + randomness; unique enough for local store
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(48)
        return f"{prefix}_{ms:x}{rnd:x}"

    def _normalize_pubmed_id(pmid):
        # Accept any non-empty string length 1..32 (schema). Do not enforce digits-only.
        if not isinstance(pmid, str):
            return None
        v = pmid.strip()
        if not v:
            return ""
        return v

    # ---- Load rows
    clients = _load("api_clients.json")
    articles = _load("articles.json")
    fetches = _load("article_fetches.json")
    search_reqs = _load("search_requests.json")

    # ---- Resolve an authenticated client context (ambient auth)
    # No credential parameter is provided, so pick any client that can serve:
    # status must be active and within rolling 24h quota.
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        return _err("UNAUTHORIZED", "No active client is available to serve this request.")
    chosen_client = None
    for c in active_clients:
        quota = c.get("daily_request_quota")
        if not isinstance(quota, int) or quota < 0:
            continue
        used = _count_calls_last_24h(c.get("id"), search_reqs, fetches)
        if used < quota:
            chosen_client = c
            break
    if chosen_client is None:
        # all active clients are at/over quota
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for all available clients in the current context.")

    client_id = chosen_client.get("id")

    # ---- Validate inputs (must not over-restrict beyond schema)
    if not isinstance(pubmed_ids, list) or len(pubmed_ids) == 0:
        return _err("VALIDATION_ERROR", "pubmed_ids must be a non-empty array of strings.")
    bad = []
    normalized = []
    for i, v in enumerate(pubmed_ids):
        nv = _normalize_pubmed_id(v)
        if nv is None:
            bad.append({"index": i, "value": v, "reason": "not_a_string"})
            continue
        if nv == "":
            bad.append({"index": i, "value": v, "reason": "empty"})
            continue
        if len(nv) > 32:
            # keep the error schema but do not reject valid <=32 strings
            bad.append({"index": i, "value": nv, "reason": "too_long"})
            continue
        normalized.append(nv)
    if bad:
        too_long = [{"index": b["index"], "value": b["value"]} for b in bad if b.get("reason") == "too_long"]
        extras = {"invalid": bad}
        if too_long:
            extras["too_long"] = too_long
        return _err("VALIDATION_ERROR", "pubmed_ids must be a non-empty array of non-empty strings of length 1..32.", **extras)

    # De-duplicate for upstream fetching (default behavior: one row per unique pubmed_id).
    unique_pmids = []
    seen = set()
    for pmid in normalized:
        if pmid not in seen:
            seen.add(pmid)
            unique_pmids.append(pmid)

    # ---- Enforce quota for this call (we will create one fetch row per unique pmid)
    # Quota is "total number of tool calls recorded in search_requests plus article_fetches created within 24h"
    # Since we will append fetch rows, ensure we don't exceed quota by this call.
    quota = int(chosen_client.get("daily_request_quota"))
    used = _count_calls_last_24h(client_id, search_reqs, fetches)
    if used + len(unique_pmids) > quota:
        return _err(
            "QUOTA_EXCEEDED",
            "Daily request quota exceeded for this client.",
            client_id=client_id,
            daily_request_quota=quota,
            used_last_24h=used,
            requested_fetches=len(unique_pmids),
        )

    # ---- Build article lookup
    articles_by_pmid = {}
    for a in articles:
        if isinstance(a, dict) and isinstance(a.get("pubmed_id"), str):
            articles_by_pmid[a["pubmed_id"]] = a

    freshness_days = 30
    freshness_cutoff = _now_utc() - datetime.timedelta(days=freshness_days)

    created_fetch_rows = []
    updated_articles = False
    nowz = _now_iso_z()

    def _article_to_detail(a):
        return {
            "pubmed_id": a.get("pubmed_id"),
            "title": a.get("title"),
            "abstract": a.get("abstract"),
            "journal": a.get("journal"),
            "publication_year": a.get("publication_year"),
            "authors": a.get("authors") if isinstance(a.get("authors"), list) else [],
            "doi": a.get("doi"),
            "pmc_id": a.get("pmc_id"),
            "source_url": a.get("source_url"),
            "status": a.get("status"),
            "fetched_at": a.get("fetched_at"),
        }

    # ---- For each unique PMID: create an article_fetches audit row and resolve/refresh article
    missing_pmids = []
    details_by_pmid = {}

    for pmid in unique_pmids:
        a = articles_by_pmid.get(pmid)
        a_status = a.get("status") if isinstance(a, dict) else None
        fetched_at = _parse_dt_any(a.get("fetched_at")) if isinstance(a, dict) else None
        cache_fresh = bool(
            isinstance(a, dict)
            and a_status == "complete"
            and fetched_at is not None
            and fetched_at >= freshness_cutoff
        )

        fetch_id = _gen_id("pmc_afc")
        fetch_row = {
            "id": fetch_id,
            "client_id": client_id,
            "pubmed_id": pmid,
            "article_id": a.get("id") if isinstance(a, dict) else None,
            "cache_hit": bool(cache_fresh),
            "status": "succeeded",  # synchronous fulfillment in this local backend
            "error_message": None,
            "remote_provider": "pubmed_eutils",
            "completed_at": nowz,
            "created_at": nowz,
            "updated_at": nowz,
        }

        # If not cache-fresh, "refetch": update or create article row with a new fetched_at.
        # We cannot call PubMed offline, so we only mark fetched_at/status coherently if record exists,
        # or create an 'unavailable' record if missing (but must still obey NOT_FOUND behavior below).
        if not cache_fresh:
            if isinstance(a, dict):
                # Lifecycle transitions allowed: partial/complete/stale/unavailable. We'll set to 'complete'
                # if it already has basic metadata (title/authors) else 'partial'. If empty, 'unavailable'.
                has_some = bool(a.get("title") or (isinstance(a.get("authors"), list) and len(a.get("authors")) > 0))
                new_status = "complete" if has_some else ("partial" if a.get("abstract") else "unavailable")
                # ensure transition is legal
                transitions = {
                    "partial": {"complete", "stale", "unavailable"},
                    "complete": {"stale", "unavailable"},
                    "stale": {"complete", "unavailable"},
                    "unavailable": {"partial", "complete"},
                }
                cur = a.get("status")
                if isinstance(cur, str) and cur in transitions and new_status != cur:
                    if new_status not in transitions[cur]:
                        # illegal transition: record failed fetch and continue
                        fetch_row["status"] = "failed"
                        fetch_row["error_message"] = f"Illegal article status transition {cur} -> {new_status}"
                        fetch_row["cache_hit"] = False
                        fetch_row["completed_at"] = nowz
                        fetch_row["updated_at"] = nowz
                        created_fetch_rows.append(fetch_row)
                        continue
                    a["status"] = new_status
                elif not isinstance(cur, str):
                    a["status"] = new_status
                a["fetched_at"] = nowz
                a["updated_at"] = nowz
                updated_articles = True
            else:
                # No article exists: create an unavailable placeholder (cannot fabricate real metadata offline)
                art_id = _gen_id("pmc_art")
                new_article = {
                    "id": art_id,
                    "pubmed_id": pmid,
                    "title": None,
                    "abstract": None,
                    "journal": None,
                    "publication_year": None,
                    "authors": [],
                    "doi": None,
                    "pmc_id": None,
                    "source_url": f"https://pubmed.ncbi.nlm.nih.gov/{pmid}/",
                    "status": "unavailable",
                    "fetched_at": nowz,
                    "created_at": nowz,
                    "updated_at": nowz,
                }
                articles.append(new_article)
                articles_by_pmid[pmid] = new_article
                fetch_row["article_id"] = art_id
                updated_articles = True

        created_fetch_rows.append(fetch_row)

        # Resolve final article for return
        resolved = articles_by_pmid.get(pmid)
        if not isinstance(resolved, dict):
            missing_pmids.append(pmid)
        else:
            # NOT_FOUND should apply when one or more cannot be resolved to stored/available metadata.
            # Treat 'unavailable' as not resolvable.
            if resolved.get("status") == "unavailable":
                missing_pmids.append(pmid)
            else:
                details_by_pmid[pmid] = _article_to_detail(resolved)

    # ---- Persist mutations
    if created_fetch_rows:
        fetches.extend(created_fetch_rows)
        _save("article_fetches.json", fetches)
    if updated_articles:
        _save("articles.json", articles)

    # ---- If any requested PubMed IDs are not resolvable, return NOT_FOUND
    if missing_pmids:
        return _err("NOT_FOUND", "One or more PubMed IDs could not be resolved to available article metadata.", missing_pubmed_ids=missing_pmids)

    # ---- Return details in the same order as requested (including duplicates)
    result_list = []
    for pmid in normalized:
        # duplicates map to the same details object content
        d = details_by_pmid.get(pmid)
        if d is None:
            # Should not happen given NOT_FOUND above, but keep deterministic
            return _err("NOT_FOUND", "One or more PubMed IDs could not be resolved to available article metadata.", missing_pubmed_ids=[pmid])
        result_list.append(d)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "object": "list",
        "data": result_list,
        "meta": {
            "endpoint": endpoint,
            "client_id": client_id,
            "unique_pubmed_ids": len(unique_pmids),
            "requested_pubmed_ids": len(pubmed_ids),
            "latency_ms": latency_ms,
        },
    }

def get_current_client(api_key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0330000" if __import__("os").path.isdir("./environment_mix/0330000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.")

    clients = _load("api_clients.json")
    search_requests = _load("search_requests.json")
    article_fetches = _load("article_fetches.json")

    # Authenticate: match by id OR client-visible key value.
    # No api_keys collection exists in schema; treat api_key as clients.id (and also allow display_name match).
    client = None
    for c in clients:
        if c.get("id") == api_key or c.get("display_name") == api_key:
            client = c
            break
    if not client:
        return _err("UNAUTHORIZED", "Invalid API key.")

    if client.get("status") == "deleted":
        return _err("UNAUTHORIZED", "Client is deleted.")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    cutoff = datetime.datetime.utcnow() - datetime.timedelta(hours=24)
    used = 0
    for r in search_requests:
        if r.get("client_id") == client.get("id"):
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                used += 1
    for f in article_fetches:
        if f.get("client_id") == client.get("id"):
            dt = _parse_dt(f.get("created_at"))
            if dt and dt >= cutoff:
                used += 1

    quota = client.get("daily_request_quota")
    remaining = None
    if isinstance(quota, int) and quota >= 0:
        remaining = max(0, quota - used)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "client": {
