def list_search_requests(api_key, status=None, query_hash=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0330000" if __import__("os").path.isdir("./environment_mix/0330000") else "/app/database")
    def _load(n):
