        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.")
    if status is not None and status not in ["queued", "running", "succeeded", "failed"]:
        return _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed.")
    if query_hash is not None and not isinstance(query_hash, str):
        return _err("VALIDATION_ERROR", "query_hash must be a string.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")
    if page_token is not None and not isinstance(page_token, str):
        return _err("VALIDATION_ERROR", "page_token must be a string.")

    clients = _load("api_clients.json")
    search_requests = _load("search_requests.json")
    article_fetches = _load("article_fetches.json")

    # Authenticate (same approach as get_current_client)
    client = None
    for c in clients:
        if c.get("id") == api_key or c.get("display_name") == api_key:
            client = c
            break
    if not client:
        return _err("UNAUTHORIZED", "Invalid API key.")

    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active.")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    ca = _parse_rfc3339(created_after)
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 timestamp.")
    cb = _parse_rfc3339(created_before)
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 timestamp.")
    if ca and cb and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before.")

    # Quota enforcement for this call (rolling 24h count of created rows in search_requests + article_fetches)
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(hours=24)
    used = 0

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    for r in search_requests:
        if r.get("client_id") == client.get("id"):
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                used += 1
    for f in article_fetches:
        if f.get("client_id") == client.get("id"):
            dt = _parse_dt(f.get("created_at"))
            if dt and dt >= cutoff:
                used += 1

    quota = client.get("daily_request_quota")
    if not isinstance(quota, int) or quota < 0:
        return _err("UNAUTHORIZED", "Client quota configuration invalid.")
    if used > quota:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", rolling_24h_calls_used=used, daily_request_quota=quota)

    # Decode page_token as cursor created_at|id
    cursor_created_at = None
    cursor_id = None
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===").decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) == 2:
                cursor_created_at = _parse_rfc3339(parts[0])
                cursor_id = parts[1]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    # Filter rows
    rows = [r for r in search_requests if r.get("client_id") == client.get("id")]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if query_hash is not None:
        rows = [r for r in rows if r.get("query_hash") == query_hash]
    if ca is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) is not None and _parse_dt(r.get("created_at")) >= ca)]
    if cb is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) is not None and _parse_dt(r.get("created_at")) < cb)]

    # Sort by created_at desc then id desc for stable order
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime.min
        return (dt, r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor (created_at desc): start after the cursor item
    if cursor_created_at is not None and cursor_id is not None:
        filtered = []
        for r in rows:
            dt = _parse_dt(r.get("created_at")) or datetime.datetime.min
            rid = r.get("id") or ""
            # skip until strictly "older" than cursor in the desc order
            if dt < cursor_created_at:
                filtered.append(r)
            elif dt == cursor_created_at and rid < cursor_id:
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:page_size]
    has_more = len(rows) > page_size

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _parse_dt(last.get("created_at")) or datetime.datetime.min
        token_raw = (last_dt.replace(microsecond=0).isoformat() + "Z") + "|" + (last.get("id") or "")
        next_cursor = base64.urlsafe_b64encode(token_raw.encode("utf-8")).decode("utf-8").rstrip("=")

    # Response
    out = []
    for r in page:
        out.append({
            "id": r.get("id"),
            "client_id": r.get("client_id"),
            "title_abstract_keywords": r.get("title_abstract_keywords") or [],
            "authors": r.get("authors") or [],
            "num_results": r.get("num_results"),
            "query_hash": r.get("query_hash"),
            "status": r.get("status"),
            "error_message": r.get("error_message"),
            "remote_provider": r.get("remote_provider"),
            "remote_request_id": r.get("remote_request_id"),
            "completed_at": r.get("completed_at"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": out,
        "meta": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_cursor,
            "latency_ms": latency_ms,
            "rolling_24h_calls_used": used,
            "daily_request_quota": quota,
        }
    }

