    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_search_request"

    def _now_utc():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo is None else s.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1])
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                return dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _count_calls_last_24h(client_id, search_requests_rows, article_fetch_rows):
        cutoff = _now_utc() - datetime.timedelta(hours=24)
        cnt = 0
        for r in search_requests_rows:
            if r.get("client_id") != client_id:
                continue
            dt = _parse_dt_any(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        for f in article_fetch_rows:
            if f.get("client_id") != client_id:
                continue
            dt = _parse_dt_any(f.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt

    # Load rows
    clients = _load("api_clients.json")
    search_reqs = _load("search_requests.json")
    fetches = _load("article_fetches.json")

    clients_rows = clients.get("rows") if isinstance(clients, dict) else clients
    search_rows = search_reqs.get("rows") if isinstance(search_reqs, dict) else search_reqs
    fetch_rows = fetches.get("rows") if isinstance(fetches, dict) else fetches

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    api_key = api_key.strip()
    id = id.strip()

    # Authenticate: api_key is the client-visible identifier (client id in this store)
    client = None
    for c in clients_rows if isinstance(clients_rows, list) else []:
        if isinstance(c, dict) and c.get("id") == api_key:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "Invalid api_key.")

    # Enforce client status and quota rules
    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active.", client_id=client.get("id"), status=client.get("status"))

    quota = client.get("daily_request_quota")
    if not isinstance(quota, int) or quota < 0:
        return _err("UNAUTHORIZED", "Client quota configuration invalid.", client_id=client.get("id"))
    used = _count_calls_last_24h(client.get("id"), search_rows if isinstance(search_rows, list) else [], fetch_rows if isinstance(fetch_rows, list) else [])
    if used >= quota:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this client.", client_id=client.get("id"), daily_request_quota=quota, used_last_24h=used)

    # Find search request row, but refuse access if not owned by this client (return NOT_FOUND)
    found = None
    for r in search_rows if isinstance(search_rows, list) else []:
        if not isinstance(r, dict):
            continue
        if r.get("id") == id and r.get("client_id") == client.get("id"):
            found = r
            break
    if found is None:
        return _err("NOT_FOUND", "Search request not found.")

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "object": "search_request",
        "endpoint": endpoint,
        "latency_ms": latency_ms,
        "data": {
            "id": found.get("id"),
            "client_id": found.get("client_id"),
            "title_abstract_keywords": found.get("title_abstract_keywords") if isinstance(found.get("title_abstract_keywords"), list) else [],
            "authors": found.get("authors") if isinstance(found.get("authors"), list) else [],
            "num_results": found.get("num_results"),
            "query_hash": found.get("query_hash"),
            "status": found.get("status"),
            "error_message": found.get("error_message"),
            "remote_provider": found.get("remote_provider"),
            "remote_request_id": found.get("remote_request_id"),
            "completed_at": found.get("completed_at"),
            "created_at": found.get("created_at"),
            "updated_at": found.get("updated_at"),
        },
    }

def list_article_fetches(api_key, status=None, pubmed_id=None, cache_hit=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0330000" if __import__("os").path.isdir("./environment_mix/0330000") else "/app/database")

    def _load(n):
