            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("timestamp must be a non-empty string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    def _client_from_api_key(api_key_value, clients):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        key = api_key_value.strip()
        for c in clients:
            if c.get("id") == key:
                return c
        for c in clients:
            if c.get("display_name") == key:
                return c
        return None

    def _count_usage_24h(client_id, search_reqs, fetches):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(hours=24)

        def _ts(row):
            v = row.get("created_at")
            if not v:
                return None
            try:
                dt = _parse_rfc3339(v)
            except Exception:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt

        n = 0
        for r in search_reqs:
            if r.get("client_id") == client_id:
                dt = _ts(r)
                if dt and dt >= cutoff:
                    n += 1
        for r in fetches:
            if r.get("client_id") == client_id:
                dt = _ts(r)
                if dt and dt >= cutoff:
                    n += 1
        return n

    t0 = time.time()
    endpoint = "list_article_fetches"
    clients = _load("api_clients.json")
    search_reqs = _load("search_requests.json")
    fetches = _load("article_fetches.json")

    client = _client_from_api_key(api_key, clients)
    if not client:
        return _err("UNAUTHORIZED", "Invalid API key")

    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active", status=client.get("status"))

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    if status is not None:
        if status not in ("queued", "running", "succeeded", "failed"):
            return _err("VALIDATION_ERROR", "Invalid status filter")

    if pubmed_id is not None and (not isinstance(pubmed_id, str) or not pubmed_id.strip()):
        return _err("VALIDATION_ERROR", "pubmed_id must be a non-empty string when provided")

    if cache_hit is not None and not isinstance(cache_hit, bool):
        return _err("VALIDATION_ERROR", "cache_hit must be boolean when provided")

    ca = None
    cb = None
    try:
        if created_after is not None:
            ca = _parse_rfc3339(created_after)
            if ca.tzinfo is None:
                ca = ca.replace(tzinfo=datetime.timezone.utc)
        if created_before is not None:
            cb = _parse_rfc3339(created_before)
            if cb.tzinfo is None:
                cb = cb.replace(tzinfo=datetime.timezone.utc)
    except Exception as e:
        return _err("VALIDATION_ERROR", "Invalid created_after/created_before timestamp", detail=str(e))

    # Quota (reads included)
    quota = client.get("daily_request_quota")
    if not isinstance(quota, int) or quota < 0:
        return _err("VALIDATION_ERROR", "Client daily_request_quota is invalid")
    used = _count_usage_24h(client.get("id"), search_reqs, fetches)
    if used >= quota:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota=quota, used_last_24h=used)

    # Pagination token: base64 json {"offset": int}
    offset = 0
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token.strip():
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            tok = json.loads(raw.decode("utf-8"))
            offset = int(tok.get("offset", 0))
            if offset < 0:
                raise ValueError("offset must be >= 0")
        except Exception as e:
            return _err("VALIDATION_ERROR", "Invalid page_token", detail=str(e))

    def _row_dt(r):
        v = r.get("created_at")
        if not v:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        try:
            dt = _parse_rfc3339(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows = [r for r in fetches if r.get("client_id") == client.get("id")]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if pubmed_id is not None:
        pid = pubmed_id.strip()
        rows = [r for r in rows if r.get("pubmed_id") == pid]
    if cache_hit is not None:
        rows = [r for r in rows if r.get("cache_hit") is cache_hit]
    if ca is not None:
        rows = [r for r in rows if _row_dt(r) >= ca]
    if cb is not None:
        rows = [r for r in rows if _row_dt(r) < cb]

    rows.sort(key=lambda r: (_row_dt(r), r.get("id", "")), reverse=True)

    total = len(rows)
    page = rows[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    latency_ms = int((time.time() - t0) * 1000)
    # Observability: log call as an article_fetches audit entry
    now = _now_iso()
    audit_id = "af_audit_" + str(int(time.time() * 1000))
    # Ensure uniqueness
    existing_ids = {x.get("id") for x in fetches}
    seq = 0
    while audit_id in existing_ids:
        seq += 1
        audit_id = f"af_audit_{int(time.time() * 1000)}_{seq}"
    fetches.append({
        "id": audit_id,
        "client_id": client["id"],
        "pubmed_id": "audit",
        "article_id": None,
        "cache_hit": False,
        "status": "succeeded",
        "error_message": None,
        "remote_provider": "pubmed_eutils",
        "completed_at": now,
        "created_at": now,
        "updated_at": now,
        "endpoint": endpoint,
        "http_status": 200,
        "latency_ms": latency_ms
    })
    _save("article_fetches.json", fetches)

    return {
        "data": page,
        "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor, "page_size": page_size}
    }

