            tok = json.loads(raw.decode("utf-8"))
            offset = int(tok.get("offset", 0))
            if offset < 0:
                raise ValueError("offset must be >= 0")
        except Exception as e:
            return _err("VALIDATION_ERROR", "Invalid page_token", detail=str(e))

    def _row_dt(r):
        v = r.get("updated_at")
        if not v:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        try:
            dt = _parse_rfc3339(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows = list(articles)
    if pid_set is not None:
        rows = [r for r in rows if r.get("pubmed_id") in pid_set]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if ua is not None:
        rows = [r for r in rows if _row_dt(r) >= ua]

    rows.sort(key=lambda r: (_row_dt(r), r.get("id", "")), reverse=True)

    total = len(rows)
    page = rows[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    # Observability/quota: log call (read included) to article_fetches as audit entry and enforce quota.
    # Quota enforcement is specified against counts of created search_requests + article_fetches.
    # This read is a tool call and must be logged; we log it via article_fetches.
    search_reqs = _load("search_requests.json")

    def _count_usage_24h(client_id, search_reqs2, fetches2):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(hours=24)

        def _ts(row):
            v = row.get("created_at")
            if not v:
                return None
            try:
                dt = _parse_rfc3339(v)
            except Exception:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt

        n = 0
        for r in search_reqs2:
            if r.get("client_id") == client_id:
                dt = _ts(r)
                if dt and dt >= cutoff:
                    n += 1
        for r in fetches2:
            if r.get("client_id") == client_id:
                dt = _ts(r)
                if dt and dt >= cutoff:
                    n += 1
        return n

    quota = client.get("daily_request_quota")
    if not isinstance(quota, int) or quota < 0:
        return _err("VALIDATION_ERROR", "Client daily_request_quota is invalid")
    used = _count_usage_24h(client.get("id"), search_reqs, fetches)
    if used >= quota:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota=quota, used_last_24h=used)

    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    latency_ms = int((time.time() - t0) * 1000)
    audit_id = "af_audit_" + str(int(time.time() * 1000))
    existing_ids = {x.get("id") for x in fetches}
    seq = 0
    while audit_id in existing_ids:
        seq += 1
        audit_id = f"af_audit_{int(time.time() * 1000)}_{seq}"
    fetches.append({
        "id": audit_id,
        "client_id": client["id"],
        "pubmed_id": "audit",
        "article_id": None,
        "cache_hit": False,
        "status": "succeeded",
        "error_message": None,
        "remote_provider": "pubmed_eutils",
        "completed_at": now,
        "created_at": now,
        "updated_at": now,
        "endpoint": endpoint,
        "http_status": 200,
        "latency_ms": latency_ms
    })
    _save("article_fetches.json", fetches)

    return {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor, "page_size": page_size}}

def update_api_client_status(api_key, status, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0330000" if __import__("os").path.isdir("./environment_mix/0330000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _client_from_api_key(api_key_value, clients):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        key = api_key_value.strip()
        for c in clients:
            if c.get("id") == key:
                return c
        for c in clients:
            if c.get("display_name") == key:
                return c
        return None

    t0 = time.time()
    endpoint = "update_api_client_status"
    clients = _load("api_clients.json")
    search_reqs = _load("search_requests.json")
    fetches = _load("article_fetches.json")

    if status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status")

    client = _client_from_api_key(api_key, clients)
    if not client:
        return _err("UNAUTHORIZED", "Invalid API key")

    # Find actual stored row reference
    idx = None
    for i, c in enumerate(clients):
        if c.get("id") == client.get("id"):
            idx = i
            break
    if idx is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    cur = clients[idx].get("status")
    if cur == "deleted":
        return _err("CONFLICT", "Client is deleted and cannot be modified")

    transitions = {
        "active": ("suspended", "deleted"),
        "suspended": ("active", "deleted"),
        "deleted": tuple()
    }
    if status == cur:
        # Idempotent: return existing record; still log the call.
        updated = clients[idx]
    else:
        if status not in transitions.get(cur, tuple()):
            return _err("INVALID_TRANSITION", "Invalid status transition", from_status=cur, to_status=status)
        now = _now_iso()
        clients[idx]["status"] = status
        clients[idx]["updated_at"] = now
        updated = clients[idx]
        _save("api_clients.json", clients)

    # Observability: log tool call in article_fetches (counts toward quota/usage logs)
    # Note: Even if client becomes suspended/deleted, this status change itself is allowed.
    now = _now_iso()
    latency_ms = int((time.time() - t0) * 1000)
    audit_id = "af_audit_" + str(int(time.time() * 1000))
    existing_ids = {x.get("id") for x in fetches}
    seq = 0
    while audit_id in existing_ids:
        seq += 1
        audit_id = f"af_audit_{int(time.time() * 1000)}_{seq}"
    fetches.append({
        "id": audit_id,
        "client_id": client["id"],
        "pubmed_id": "audit",
        "article_id": None,
        "cache_hit": False,
        "status": "succeeded",
        "error_message": None,
        "remote_provider": "pubmed_eutils",
        "completed_at": now,
        "created_at": now,
        "updated_at": now,
        "endpoint": endpoint,
        "http_status": 200,
        "latency_ms": latency_ms
    })
    _save("article_fetches.json", fetches)

    return {"data": updated}
